def _sigmoid(z):
    if z >= 0:
        return 1.0 / (1.0 + _math.exp(-z))
    e = _math.exp(z)
    return e / (1.0 + e)


class Guardian:
    def __init__(self):
        m = _MODELO
        self.names = m["names"]
        self.mean, self.scale, self.coef = m["mean"], m["scale"], m["coef"]
        self.intercept = m["intercept"]
        self.base = m["gbm"]["base"]
        self.trees = m["gbm"]["trees"]
        self.w = m["w_ens"]
        self.corte = m["corte"]
        self.corte_multi = m.get("corte_multi", m["corte"])

    def _lr(self, x):
        z = self.intercept
        for v, mu, sd, c in zip(x, self.mean, self.scale, self.coef):
            z += c * (v - mu) / (sd or 1.0)
        return _sigmoid(z)

    def _gbm(self, x):
        z = self.base
        for nodes in self.trees:
            i = 0
            while not nodes[i][4]:
                f, thr, left, right = nodes[i][0], nodes[i][1], nodes[i][2], nodes[i][3]
                i = left if x[f] <= thr else right
            z += nodes[i][5]
        return _sigmoid(z)

    def sentence_scores(self, caso):
        out = []
        for f in case_sentence_features(caso):
            x = [float(f.get(n, 0.0)) for n in self.names]
            out.append(self.w * self._lr(x) + (1 - self.w) * self._gbm(x))
        return out

    def raw(self, caso):
        return max(self.sentence_scores(caso))

    def _corte(self, caso):
        n = len((caso.get("senales") or {}).get("oraciones") or [])
        return self.corte_multi if n >= 2 else self.corte

    def score(self, caso):
        try:
            p = self.raw(caso)
            t = self._corte(caso)
        except Exception:
            return 0.5  # ante un caso malformado, mejor revisar que dejar pasar
        # reescalado monótono a trozos: el corte t pasa a ser 0,5
        if p < t:
            return 0.5 * p / t
        return 0.5 + 0.5 * (p - t) / (1 - t)
